// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }

    function testFuzz_property(address logAddr) public {
        // SetLogFile is only allowed before initialization; stay in the admissible domain
        vm.assume(logAddr != address(0));

        // drive c through SetLogFile with a fuzzed log address (no SetMinSum call)
        c.SetLogFile(logAddr);

        // Rule: configuring the log file must not alter MinSum.
        // Reference C: MinSum stays 0. Mutant: MinSum == uint256(uint160(logAddr)) != 0.
        assertTrue(c.MinSum() == 0);
    }
}
